{
  "application": "ppt-generation",
  "case_id": "case-sequoia-genai-act2",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "venture capital investors and startup founders evaluating generative AI opportunities",
    "tone": "data-forward, analytical, narrative"
  },
  "brief": {
    "title": "Generative AI's Act Two: From Technology Hammer to Real Value",
    "one_liner": "Sequoia Capital's analysis of how generative AI is transitioning from novelty demos to end-to-end solutions that solve real human problems, with data on retention, revenue, and market structure.",
    "goal": "Understand the shift from Act 1 (technology-out) to Act 2 (customer-back) in generative AI, recognize the retention challenges facing AI-first apps versus incumbents, and identify the characteristics of companies likely to win in the next phase."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "Generative AI's Act Two: From Technology Hammer to Real Value",
      "objective": "Cover slide with the deck title, Sequoia Capital attribution, and publication date (September 2023). Set the stage with a compelling visual framing."
    },
    {
      "id": "decades-of-convergence",
      "title": "Six Decades of Technological Progress Converged to Enable Generative AI",
      "objective": "Present the three foundational technology waves — Moore's Law (6 decades of compute), the internet (4 decades of training data), and mobile/cloud (2 decades of distribution) — as a timeline or layered visual showing how they accumulated to create the conditions for generative AI."
    },
    {
      "id": "genai-outpaces-saas",
      "title": "GenAI Startups Surpassed $1B Revenue Faster Than SaaS Ever Did",
      "objective": "Highlight the rapid commercial traction of generative AI startups, noting >$1B in startup revenue in months versus years for SaaS. Reference standout examples: ChatGPT (fastest-growing app), Midjourney (hundreds of millions in revenue with 11 employees), and Character.ai (2-hour average session time)."
    },
    {
      "id": "retention-gap-incumbents-vs-ai",
      "title": "AI-First Apps Show 14% Median Retention vs. 51% for Incumbents",
      "objective": "Present a comparative bar chart or side-by-side visualization using the mobile app retention data. Incumbents (WhatsApp 85%, Instagram 64%, YouTube 64%, TikTok 60%, Snapchat 51%, Roblox 41%, Tinder 34%, Candy Crush 32%, Duolingo 30%) vs. AI-First Companies (Character.ai 41%, Runway 27%, Remini 14%, ChatGPT 14%, Lensa 12%). Emphasize the stark median gap: 51% vs. 14%."
    },
    {
      "id": "incumbent-monthly-usage",
      "title": "YouTube Leads Incumbents at 85% Monthly Active Usage",
      "objective": "Show the second incumbent benchmark chart with monthly usage rates: YouTube 85%, Instagram 73%, TikTok 69%, Snapchat 67%, WhatsApp 63%, Roblox 61%, Tinder 54%, Duolingo 50%, Candy Crush 48%, with a 63% median. This contextualizes the high bar AI apps must clear."
    },
    {
      "id": "act1-vs-act2",
      "title": "Act 1 Was Technology-Out; Act 2 Is Customer-Back",
      "objective": "Create a two-column comparison contrasting Act 1 (foundation models as the entire solution, novelty demos, lightweight wrappers, poor retention) versus Act 2 (foundation models as a piece of a comprehensive solution, new editing interfaces, multi-modal workflows, end-to-end problem solving). Reference Harvey, Glean, Character, and Ava as Act 2 exemplars."
    },
    {
      "id": "market-map-evolution",
      "title": "Market Map Reorganized by Use Case, Not Model Modality",
      "objective": "Present the conceptual shift in how the Sequoia generative AI market map is now organized — from model modality (text, image, code) to use case, reflecting the evolution from technology hammer to actual value delivery. Emphasize the increasingly multi-modal nature of applications, referencing Act 2 exemplars like Harvey (legal), Glean (enterprise search), Character and Ava (companionship) as illustrations of use-case-driven categories. Note that this reorganization mirrors the broader Act 1 to Act 2 transition."
    },
    {
      "id": "takeaways-for-builders-investors",
      "title": "Key Takeaways: What Separates Winners in Act Two",
      "objective": "Summarize 4-5 actionable implications: (1) Retention is the critical challenge — AI-first apps at 14% median vs. 51% for incumbents; (2) Foundation models should be a component, not the whole product; (3) Multi-modal, workflow-integrated solutions will win; (4) The $1B+ revenue milestone proves real demand exists despite hype cycles; (5) Companies solving end-to-end human problems will define Act 2."
    }
  ]
}

