const pptxgen = require("pptxgenjs");
const slideConfig = { type: 'cover', index: 1, title: 'Generative AI\'s Act Two: From Technology Hammer to Real Value' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.8, y: 1.5, w: 8.4, h: 2.0,
    fontSize: 44, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left", valign: "bottom"
  });

  // Subtitle
  slide.addText("Sequoia Capital Analysis", {
    x: 0.8, y: 3.6, w: 8.4, h: 0.6,
    fontSize: 24, fontFace: "Arial",
    color: theme.accent, bold: true, align: "left", valign: "top"
  });

  // Date
  slide.addText("September 2023", {
    x: 0.8, y: 4.2, w: 8.4, h: 0.5,
    fontSize: 18, fontFace: "Arial",
    color: theme.secondary, align: "left", valign: "top"
  });

  // Decorative line
  slide.addShape(pres.shapes.LINE, {
    x: 0.8, y: 3.5, w: 8.4, h: 0,
    line: { color: theme.accent, width: 3 }
  });

  return slide;
}
module.exports = { createSlide, slideConfig };

const pptxgen = require("pptxgenjs");
const slideConfig = { type: 'content', index: 2, title: 'Six Decades of Technological Progress Converged to Enable Generative AI' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, { x: 0.5, y: 0.3, w: 9, h: 0.8, fontSize: 24, fontFace: "Arial", color: theme.primary, bold: true });

  // Add page badge
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("2", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  const boxes = [
    { title: "Moore's Law", subtitle: "6 Decades", desc: "Delivered compute horsepower to process exaflops of data", x: 1.0 },
    { title: "The Internet", subtitle: "4 Decades", desc: "Produced trillions of tokens of training data", x: 4.0 },
    { title: "Mobile & Cloud", subtitle: "2 Decades", desc: "Put a supercomputer in every human's palm", x: 7.0 }
  ];

  boxes.forEach(box => {
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: box.x, y: 2.0, w: 2.5, h: 2.2,
      fill: { color: theme.light },
      rectRadius: 0.1
    });

    slide.addText(box.title, {
      x: box.x, y: 2.2, w: 2.5, h: 0.5,
      fontSize: 22, fontFace: "Arial", color: theme.primary, bold: true, align: "center"
    });

    slide.addText(box.subtitle, {
      x: box.x, y: 2.7, w: 2.5, h: 0.3,
      fontSize: 16, fontFace: "Arial", color: theme.accent, bold: true, align: "center"
    });

    slide.addText(box.desc, {
      x: box.x + 0.1, y: 3.1, w: 2.3, h: 0.8,
      fontSize: 14, fontFace: "Arial", color: theme.secondary, align: "center", valign: "top"
    });
  });

  // Connecting arrows
  slide.addShape(pres.shapes.RIGHT_ARROW, { x: 3.6, y: 3.0, w: 0.3, h: 0.3, fill: { color: theme.accent } });
  slide.addShape(pres.shapes.RIGHT_ARROW, { x: 6.6, y: 3.0, w: 0.3, h: 0.3, fill: { color: theme.accent } });

  return slide;
}
module.exports = { createSlide, slideConfig };

