const slideConfig = { type: 'content', index: 3, title: 'GenAI Startups Surpassed $1B Revenue Faster Than SaaS Ever Did' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, { x: 0.5, y: 0.3, w: 9, h: 0.8, fontSize: 24, fontFace: "Arial", color: theme.primary, bold: true });
  // Badge
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("3", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  slide.addText("Generative AI reached $1B in startup revenue in months, a milestone that took SaaS years to achieve.", {
    x: 0.5, y: 1.3, w: 9, h: 0.6, fontSize: 18, fontFace: "Arial", color: theme.secondary, bold: true
  });

  const cards = [
    { title: "ChatGPT", desc: "Fastest-growing application in history with strong PMF among students and developers.", y: 2.2 },
    { title: "Midjourney", desc: "Reported hundreds of millions of dollars in revenue with a team of just 11 people.", y: 3.2 },
    { title: "Character.ai", desc: "Popularized AI companionship. Users spend an average of 2 hours per session in-app.", y: 4.2 }
  ];

  cards.forEach(card => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: card.y, w: 2.5, h: 0.8,
      fill: { color: theme.primary }
    });
    slide.addText(card.title, {
      x: 0.5, y: card.y, w: 2.5, h: 0.8,
      fontSize: 22, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 3.1, y: card.y, w: 6.4, h: 0.8,
      fill: { color: theme.light }
    });
    slide.addText(card.desc, {
      x: 3.3, y: card.y, w: 6.0, h: 0.8,
      fontSize: 16, fontFace: "Arial", color: theme.secondary, align: "left", valign: "middle"
    });
  });

  return slide;
}
module.exports = { createSlide, slideConfig };

const pptxgen = require("pptxgenjs");
const slideConfig = { type: 'content', index: 4, title: 'AI-First Apps Show 14% Median Retention vs. 51% for Incumbents' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText(slideConfig.title, { x: 0.5, y: 0.3, w: 9, h: 0.8, fontSize: 24, fontFace: "Arial", color: theme.primary, bold: true });
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("4", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  const chartDataIncumbent = [
    {
      name: "Incumbents (Median: 51%)",
      labels: ["WhatsApp", "Instagram", "YouTube", "TikTok", "Snapchat", "Roblox", "Tinder", "Candy Crush", "Duolingo"],
      values: [85, 64, 64, 60, 51, 41, 34, 32, 30]
    }
  ];

  const chartDataAI = [
    {
      name: "AI-First (Median: 14%)",
      labels: ["Character.ai", "Runway", "Remini", "ChatGPT", "Lensa"],
      values: [41, 27, 14, 14, 12]
    }
  ];

  const chartOptsIncumbent = {
    x: 0.5, y: 1.5, w: 4.2, h: 3.5,
    barDir: "col",
    showValue: true,
    showLegend: true, legendPos: "t",
    chartColors: [theme.secondary],
    dataLabelFormatCode: "0'%'",
    valAxisMaxVal: 100,
    catAxisLabelColor: theme.primary,
    valAxisLabelColor: theme.secondary,
    dataLabelColor: theme.primary,
    dataLabelFontFace: "Arial",
    dataLabelPosition: "outEnd"
  };

  const chartOptsAI = {
    x: 5.0, y: 1.5, w: 4.2, h: 3.5,
    barDir: "col",
    showValue: true,
    showLegend: true, legendPos: "t",
    chartColors: [theme.accent],
    dataLabelFormatCode: "0'%'",
    valAxisMaxVal: 100,
    catAxisLabelColor: theme.primary,
    valAxisLabelColor: theme.secondary,
    dataLabelColor: theme.primary,
    dataLabelFontFace: "Arial",
    dataLabelPosition: "outEnd"
  };

  slide.addChart(pres.charts.BAR, chartDataIncumbent, chartOptsIncumbent);
  slide.addChart(pres.charts.BAR, chartDataAI, chartOptsAI);

  return slide;
}
module.exports = { createSlide, slideConfig };

